  });

  // 端口上界 65535 由 schema max 强制
  it("port 超 schema 上界抛错", () => {
    expect(() => Config({ port: 65536 })).toThrow();
  });

  it("httpsPort 负数抛错", () => {
    expect(() => Config({ httpsPort: -1 })).toThrow();
  });

  it("压缩档位超 3 抛错", () => {
    expect(() => Config({ httpCompressLevel: 4 })).toThrow();
  });
});

